import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, Object3D } = ctx.THREE;

  // Root container
  const root = new Group();
  root.position.set(0, -0.2, 0);

  // Track resources for cleanup
  const timelines = [];
  const materials = [];
  const primitiveCleanups = [];

  // Load the gear mesh
  let meshLoaded = false;
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    if (!root.userData.disposed) {
      const scene = gltf.scene;
      scene.traverse((node) => {
        if (node.isMesh) {
          // Preserve original material if it exists; wrap in NodeMaterial if needed
          if (node.material && !node.material.isNodeMaterial) {
            const originalMat = node.material;
            const nodeMat = new MeshStandardNodeMaterial({
              color: originalMat.color || 0xcccccc,
              metalness: originalMat.metalness ?? 0.45,
              roughness: originalMat.roughness ?? 0.6,
              emissive: originalMat.emissive || 0x000000,
              emissiveIntensity: 0,
            });
            node.material = nodeMat;
            materials.push(nodeMat);
          }
        }
      });
      root.add(scene);
      meshLoaded = true;

      // Apply accent rim light locally to highlight the gear
      const rimLight = new ctx.THREE.PointLight(0xff2a38, 0.7, 4);
      rimLight.position.set(1, 1, 1);
      root.add(rimLight);
    }
  });

  // Apply parallax-scroll primitive (trigger: scroll)
  const parallaxResult = ctx.primitives['parallax-scroll'](root, {
    intensity: 0.4,
  });
  if (parallaxResult) {
    primitiveCleanups.push(parallaxResult.cleanup);
  }

  // Apply magnetic-cursor primitive (trigger: hover)
  const magneticResult = ctx.primitives['magnetic-cursor'](root, {
    radius: 1.2,
    strength: 0.35,
  });
  if (magneticResult) {
    primitiveCleanups.push(magneticResult.cleanup);
  }

  // Hover interaction: rise-in entrance
  let hoverTimeline = null;
  root.userData.handlers = {
    hover: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(root.position, {
        y: root.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
      });
      timelines.push(hoverTimeline);
    },
    unhover: () => {
      if (hoverTimeline) hoverTimeline.kill();
      hoverTimeline = gsap.to(root.position, {
        y: -0.2,
        duration: 0.9,
        ease: 'power4.out',
        overwrite: 'auto',
      });
      timelines.push(hoverTimeline);
    },
    click: () => {
      ctx.emit('hub-collection.select', {});
    },
  };

  // Cleanup function
  root.userData.cleanup = () => {
    root.userData.disposed = true;
    timelines.forEach((tl) => {
      if (tl && tl.kill) tl.kill();
    });
    materials.forEach((mat) => {
      if (mat && mat.dispose) mat.dispose();
    });
    primitiveCleanups.forEach((fn) => {
      if (fn) fn();
    });
  };

  return root;
}
